import phylotreelib as pt

from Bio import Phylo


def convert_phylo_to_nodes(tree):
    """
    Convert a Bio.Phylo tree into the flattened node
    representation used by the React tree visualisation.
    """

    nodes = []

    def add_node(clade):
        # Reserve an index before processing children.
        # This ensures parents have lower indices than children.
        node_index = len(nodes)
        nodes.append(None)

        children = [
            add_node(child)
            for child in clade.clades
        ]

        # Number of descendant terminal sequences
        if clade.is_terminal():
            sequence_count = 1
        else:
            sequence_count = sum(
                nodes[child]["nt"]
                for child in children
            )

        node = {
            "c": children,
            "b": clade.branch_length or 0.0,
            "nt": sequence_count,
            "mj": -1,
            "sc": -1
        }

        # Terminal nodes represent individual sequences
        if clade.is_terminal():
            node["n"] = clade.name

        # Internal node support values
        if clade.confidence is not None:
            node["s"] = str(clade.confidence)

        nodes[node_index] = node

        return node_index

    add_node(tree.root)

    return nodes


